steps.script:
function extract(input) {
    var o = JSON.parse(JSON.parse(input).text);
    if (o.code !== 0) { throw new Error("view API code=" + o.code + " " + (o.message || "")); }
    var d = o.data || {};
    return JSON.stringify({
        title:       d.title || "",
        description: d.desc || "",
        coverURL:    d.pic || "",
        duration:    d.duration || 0,
        aid:         String(d.aid || ""),
        cid:         String(d.cid || ""),
        bvid:        d.bvid || "",
        author:      (d.owner && d.owner.name) || ""
    });
}

function extract(input) {
    var o = JSON.parse(JSON.parse(input).text);
    if (o.code !== 0) { throw new Error("playurl API code=" + o.code + " " + (o.message || "")); }
    var d = o.data || {};
    var url = "";
    var durl = d.durl || [];
    if (durl.length && durl[0].url) {
        url = durl[0].url;                      // 首选：音画合一的完整文件
    } else if (d.dash && d.dash.video && d.dash.video.length) {
        for (var i = 0; i < d.dash.video.length; i++) {
            var v = d.dash.video[i];
            if (v.baseUrl) { url = v.baseUrl; break; }
            if (v.base_url) { url = v.base_url; break; }
        }
    }
    if (!url) { throw new Error("接口没给播放地址"); }
    return JSON.stringify({ videoURL: url });
}

(function() {
    // 快手解析页面脚本（platformsV2 / fetch.method=webview）。
    // 职责：拦截 GraphQL 响应（或从 __APOLLO_STATE__ / DOM 兜底）拿 photo 对象，
    // 在页面内完成字段抽取（对标 Swift 旧链路 parseKuaishouPhotoJSON），
    // 通过固定桥 pluginResult 回传字段字典，pluginLog 回传诊断日志。
    // 无占位符（占位符红线事故 2026-08-11 的规避：热更脚本里不允许出现需 Swift 替换的标记）。

    if (window.__ksPluginInjected) return;
    window.__ksPluginInjected = true;

    // 诊断日志限流：页面请求很吵，总量封顶防刷屏
    var logCount = 0;
    function postLog(msg) {
        if (logCount >= 80) return;
        logCount++;
        try { window.webkit.messageHandlers.pluginLog.postMessage(String(msg)); } catch (e) {}
    }

    // 版本标记 + 页面真实地址（排查 pathname 不含 short-video 导致全树兜底失效的情况）
    try { postLog('v1.3.8 url=' + (window.location.href || '').slice(0, 120) + ' pageId=' + (photoIdFromLocation() || 'null')); } catch (e) {}

    // 每个被拦截响应的顶层键名（限前 12 条）：看清页面到底在哪些响应里拿数据
    var inspectCount = 0;
    function inspect(d, url) {
        scan(d);
        var u = String(url || '');
        // once（分享数据）接口深挖：顶层只有 {result}，直接看整体结构
        if (u.indexOf('/rest/zt/share/w/tp/once') !== -1 && d && typeof d === 'object') {
            postLog('once body=' + JSON.stringify(d).slice(0, 300));
        }
        // brilliantData（发现页/首页流）深挖：找目标视频的数据结构
        if (d && d.data && d.data.brilliantData && typeof d.data.brilliantData === 'object') {
            postLog('brilliant body=' + JSON.stringify(d.data.brilliantData).slice(0, 300));
        }
        if (inspectCount < 12 && d && typeof d === 'object') {
            inspectCount++;
            var ks;
            if (d.data && typeof d.data === 'object') {
                ks = 'data{' + Object.keys(d.data).join(',').slice(0, 110) + '}';
            } else {
                ks = '{' + Object.keys(d).join(',').slice(0, 110) + '}';
            }
            postLog('RESP ' + u.replace(/^https?:\/\//, '').slice(0, 55) + ' -> ' + ks);
        }
    }
    function postResult(obj) {
        try { window.webkit.messageHandlers.pluginResult.postMessage(JSON.stringify(obj)); } catch (e) {}
    }

    // ---- 字段抽取（与旧 Swift 链路同源，字段清单来自规则包 kuaishou 段） ----
    var TITLE_FIELDS = ['caption', 'originCaption', 'title', 'name'];
    var DESC_FIELDS = ['caption', 'originCaption', 'description', 'desc', 'content'];
    var VIDEO_FIELDS = ['srcNoMark', 'photoUrl', 'mainMvUrl', 'mainMvUrls', 'playUrl', 'videoUrl', 'mvUrl', 'mvPlayUrl'];
    var COVER_FIELDS = ['coverUrl', 'coverUrls'];
    var ATLAS_PATHS = ['ext_params.atlas.list', 'atlas.list'];
    var ATLAS_PREFIX = 'https://tx2.a.yximgs.com/';
    var MAX_IMAGES = 50;

    // 兼容 字符串 / [String] 首元素 / [{url}|{urlDefault}] 首元素
    function firstField(dict, keys) {
        if (!dict) return '';
        for (var i = 0; i < keys.length; i++) {
            var v = dict[keys[i]];
            if (typeof v === 'string' && v) return v;
            if (Object.prototype.toString.call(v) === '[object Array]') {
                for (var j = 0; j < v.length; j++) {
                    var item = v[j];
                    if (typeof item === 'string' && item) return item;
                    if (item && typeof item === 'object') {
                        var u = item.url || item.urlDefault;
                        if (typeof u === 'string' && u) return u;
                    }
                }
            }
        }
        return '';
    }

    function valueAtPath(root, path) {
        var parts = path.split('.');
        var node = root;
        for (var i = 0; i < parts.length; i++) {
            if (!node || typeof node !== 'object') return null;
            node = node[parts[i]];
        }
        return node;
    }

    // 图集：atlas.list 末端是相对路径数组（或 [{url}]），拼 atlasPrefix
    function atlasImages(dict) {
        var out = [];
        for (var i = 0; i < ATLAS_PATHS.length; i++) {
            var node = valueAtPath(dict, ATLAS_PATHS[i]);
            if (Object.prototype.toString.call(node) === '[object Array]') {
                for (var j = 0; j < node.length; j++) {
                    var item = node[j];
                    var rel = (item && typeof item === 'object') ? (item.url || '') : item;
                    if (typeof rel === 'string' && rel) {
                        out.push((rel.indexOf('http://') === 0 || rel.indexOf('https://') === 0) ? rel : ATLAS_PREFIX + rel);
                    }
                }
            }
            if (out.length) break;
        }
        var seen = {}, uniq = [];
        for (var k = 0; k < out.length; k++) {
            if (!seen[out[k]]) { seen[out[k]] = 1; uniq.push(out[k]); }
        }
        return uniq.slice(0, MAX_IMAGES);
    }

    function extractFields(photo) {
        var title = firstField(photo, TITLE_FIELDS);
        var desc = firstField(photo, DESC_FIELDS);
        var cover = firstField(photo, COVER_FIELDS);
        var video = firstField(photo, VIDEO_FIELDS);
        var images = video ? [] : atlasImages(photo);
        return {
            title: title || desc || '',
            description: desc || title || '',
            coverURL: cover || '',
            videoURL: video || '',
            imageURLs: images
        };
    }

    // ---- photo 捕获 ----
    var didCapture = false;
    function handlePhoto(photo, src) {
        if (didCapture || !photo || typeof photo !== 'object') return;
        var fields = extractFields(photo);
        var hasMedia = fields.videoURL || (fields.imageURLs && fields.imageURLs.length);
        if (!hasMedia) return;
        didCapture = true;
        postLog('captured via ' + src + ' video=' + !!fields.videoURL + ' images=' + fields.imageURLs.length);
        postResult(fields);
    }

    function photoIdFromLocation() {
        try {
            var parts = (window.location.pathname || '').split('/');
            for (var i = 0; i < parts.length - 1; i++) {
                if (parts[i] === 'short-video' && parts[i + 1]) return parts[i + 1];
            }
        } catch (e) {}
        return null;
    }

    // 认两种查询名的 photo（visionShortVideoReco 推荐挂载 / visionVideoDetail 详情接口），
    // 另加全树兜底：任何位置出现「ID 匹配页面地址」的照片对象都收（防查询名再改版）。
    // feeds（推荐流）照片 ID 不匹配页面地址，不会误抓。
    function looksLikeTargetPhoto(obj, expect) {
        if (!obj || typeof obj !== 'object') return false;
        if (expect == null) return false;
        // id 可能是数字 ID，photoId 可能是 base62 token，两个都试
        var oid = (obj.id != null) ? String(obj.id)
                : (obj.photoId != null ? String(obj.photoId) : '');
        if (oid !== String(expect)) return false;
        return !!(obj.caption || obj.coverUrls || obj.srcNoMark || obj.mainMvUrls
                  || obj.mainMvUrl || obj.photoUrl || obj.ext_params);
    }

    function scan(obj) {
        if (!obj || typeof obj !== 'object') return;
        if (obj.data && obj.data.visionShortVideoReco) {
            var reco = obj.data.visionShortVideoReco;
            if (reco.photo) { handlePhoto(reco.photo, 'reco.photo'); return; }
            // feeds 按页面 ID 精确匹配（photo.id 是 base62 token，与 URL 同源）。
            // 绝不盲取 feeds[0]：未登录分享页环境里 feeds 全是推荐，盲取会抓错视频（2026-09-11 实锤）。
            var expectR = photoIdFromLocation();
            if (reco.feeds && reco.feeds.length) {
                var found = false;
                for (var fi = 0; fi < reco.feeds.length; fi++) {
                    var p = reco.feeds[fi] && reco.feeds[fi].photo;
                    if (p && expectR != null && String(p.id) === String(expectR)) {
                        handlePhoto(p, 'feeds[' + fi + '].photo');
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    postLog('reco: no feed photo matches pageId=' + (expectR || 'null')
                            + ', feeds=' + reco.feeds.length);
                }
            } else {
                postLog('reco present but no photo, keys=' + Object.keys(reco).join(','));
            }
        }
        if (obj.data && obj.data.visionVideoDetail) {
            var det = obj.data.visionVideoDetail;
            if (det.photo) { handlePhoto(det.photo, 'visionVideoDetail.photo'); return; }
            postLog('visionVideoDetail present but no photo, keys=' + Object.keys(det).join(','));
        }
        var expect = photoIdFromLocation();
        if (expect != null && looksLikeTargetPhoto(obj, expect)) {
            handlePhoto(obj, 'deep:' + (obj.__typename || 'photo'));
            return;
        }
        for (var k in obj) {
            if (Object.prototype.hasOwnProperty.call(obj, k)) {
                try { scan(obj[k]); } catch (e) {}
            }
        }
    }

    // 兜底封面：poster → og:image → 页面快手图床 img → CSS 背景图。
    // 只认 /upic/ 路径（视频封面），排除 /uhead/（用户头像，2026-09-11 实锤会误当封面）。
    function domCover() {
        var ok = function(s) {
            return s && s.indexOf('http') === 0
                && (s.indexOf('/upic/') !== -1 || s.indexOf('photoc') !== -1);
        };
        try {
            var el = document.querySelector('video');
            if (el && ok(el.poster)) return el.poster;
            var meta = document.querySelector('meta[property="og:image"]');
            if (meta && ok(meta.content)) return meta.content;
            var imgs = document.querySelectorAll('img');
            for (var i = 0; i < imgs.length; i++) {
                var s = imgs[i].src || '';
                if (ok(s) && (s.indexOf('yximgs.com') !== -1 || s.indexOf('kwimgs.com') !== -1)) return s;
            }
            var all = document.querySelectorAll('[style*="background-image"]');
            for (var j = 0; j < all.length; j++) {
                var bg = (all[j].style && all[j].style.backgroundImage) || '';
                var m = bg.match(/url\(["']?(https?:[^"')]+)["']?\)/);
                if (m && ok(m[1]) && (m[1].indexOf('yximgs.com') !== -1 || m[1].indexOf('kwimgs.com') !== -1)) return m[1];
            }
        } catch (e) {}
        return '';
    }

    // 兜底：__APOLLO_STATE__ 的 PhotoEntity 缓存 → 页面 <video> 元素
    function domFallback() {
        if (didCapture) return;
        try {
            var state = window.__APOLLO_STATE__;
            if (state && typeof state === 'object') {
                var expect = photoIdFromLocation();
                var targetKey = expect ? ('PhotoEntity:' + expect) : null;
                if (targetKey && state[targetKey]) {
                    handlePhoto(state[targetKey], 'apollo:' + targetKey);
                    return;
                }
                for (var key in state) {
                    if (Object.prototype.hasOwnProperty.call(state, key)) {
                        var entry = state[key];
                        if (entry && entry.__typename === 'PhotoEntity'
                            && expect != null && String(entry.id) === String(expect)) {
                            handlePhoto(entry, 'apollo:' + key);
                            return;
                        }
                    }
                }
                // 列出 Apollo 里实际存在的 PhotoEntity ID，判断目标是没到还是 ID 对不上
                var entityIds = [];
                for (var k2 in state) {
                    if (Object.prototype.hasOwnProperty.call(state, k2)
                        && state[k2] && state[k2].__typename === 'PhotoEntity') {
                        entityIds.push(String(state[k2].id || k2));
                        if (entityIds.length >= 6) break;
                    }
                }
                postLog('apollo no target, pageId=' + (expect || 'null')
                        + (entityIds.length ? ', entities=' + entityIds.join(',') : ', no PhotoEntity'));
            }
        } catch (e) { postLog('apollo fallback error: ' + (e && e.message)); }
        try {
            var el = document.querySelector('video');
            if (el) {
                var src = el.currentSrc || el.src || '';
                if (src && src.indexOf('http') === 0) {
                    handlePhoto({ srcNoMark: src, caption: document.title || '', coverUrl: domCover() },
                                'video-element');
                }
            }
        } catch (e) { postLog('dom fallback error: ' + (e && e.message)); }
    }
    setTimeout(domFallback, 3000);
    setTimeout(domFallback, 5000);
    setTimeout(domFallback, 8000);
    setTimeout(domFallback, 12000);

    // ---- 拦截 fetch / XMLHttpRequest（与旧内置拦截脚本同策略） ----
    function isKsGraphQL(url, body) {
        var u = String(url || ''), b = (typeof body === 'string') ? body : '';
        return u.indexOf('graphql') !== -1
            || b.indexOf('photoId') !== -1
            || b.indexOf('visionVideoDetail') !== -1
            || b.indexOf('visionShortVideoReco') !== -1;
    }

    var originalFetch = window.fetch;
    if (originalFetch) {
        window.fetch = function() {
            var input = arguments[0], init = arguments[1] || {};
            var url = (typeof input === 'string') ? input : (input && input.url) || '';
            var body = init.body;
            var isGraph = isKsGraphQL(url, body);
            if (isGraph) postLog('[REQ] FETCH ' + url);
            var p = originalFetch.apply(this, arguments);
            if (isGraph) {
                p.then(function(response) {
                    try {
                        response.clone().json().then(function(d) { inspect(d, url); })
                            .catch(function(e) { postLog('resp parse fail (fetch): ' + url.slice(0, 60)); });
                    } catch (e) {}
                }).catch(function() {});
            }
            return p;
        };
    }

    var originalOpen = XMLHttpRequest.prototype.open;
    var originalSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open = function(method, url) {
        this.__pluginUrl = String(url || '');
        return originalOpen.apply(this, arguments);
    };
    XMLHttpRequest.prototype.send = function(body) {
        var self = this, url = this.__pluginUrl || '';
        if (isKsGraphQL(url, body)) {
            postLog('[REQ] XHR ' + url);
            this.addEventListener('load', function() {
                try {
                    inspect(JSON.parse(self.responseText), url);
                } catch (e) {
                    postLog('resp parse fail (xhr): ' + url.slice(0, 60)
                            + ' len=' + (self.responseText || '').length);
                }
            });
        }
        return originalSend.apply(this, arguments);
    };
})();

// 抖音分享页 · warmup 步（建议在同一 URL 上跑两次）—— 只为让服务端下发 ttwid cookie。
//
// 为什么需要：引擎 http 步骤共用 URLSessionConfiguration.default，cookie 自动进
// HTTPCookieStorage.shared。但抖音分享页**首次请求常只回 33KB 壳页**（「抱歉出错了」），
// 同时在 Set-Cookie 里下发 ttwid；带 ttwid 再请求同一 URL 才返回完整 SSR（160KB+）。
//
// ⚠️ 为什么要跑两次：ttwid 是否下发有随机性 —— 实测单次约 2/3 命中（真实 URLSession 6 轮
// 里 2 轮完全不下发）。单次 warmup 成功率仅 4/6，**前置两次后 6/6**。所以规则里应有
// warmup + warmup2 两步（脚本可原样复用），第三步 detail 才取数据。
//
// ⚠️ UA 必须移动端：桌面 UA 打分享页第二次只有 6.3KB 空壳，iPhone UA 才有 161KB。
// ⚠️ 不要 warmup 首页（www.iesdouyin.com/）：它下发的 __ac_nonce 会让后续分享页反而回
//    6.3KB 空壳（实测 0/3）——warmup 与 detail 必须用同一个分享页 URL。

function dyRiskControl(html) {
  // 只用「风控页面专有」的中文信号。正常分享页也会引用 TTGCaptcha SDK（含 captcha /
  // verifyCenter 字样），把 SDK 引用词当信号会误判所有正常页——故不列英文 SDK 词。
  var signals = ['人机验证', '安全验证', '验证码', '请完成验证', '滑块验证'];
  for (var i = 0; i < signals.length; i++) {
    if (html.indexOf(signals[i]) >= 0) return true;
  }
  return false;
}

// ⚠️ warmup 步必须「静默成功」：引擎按序跑完所有步骤，任一步报 error 就终止 ——
// 若这里对壳页报 error，后面的 detail 步根本不会被执行。
function extract(input) {
  var html = '';
  try { html = (JSON.parse(input).text) || ''; } catch (e) {}
  if (dyRiskControl(html)) return JSON.stringify({ rateLimited: true });
  return JSON.stringify({ warmup: 'ok' });
}

// 抖音分享页 · warmup 步（建议在同一 URL 上跑两次）—— 只为让服务端下发 ttwid cookie。
//
// 为什么需要：引擎 http 步骤共用 URLSessionConfiguration.default，cookie 自动进
// HTTPCookieStorage.shared。但抖音分享页**首次请求常只回 33KB 壳页**（「抱歉出错了」），
// 同时在 Set-Cookie 里下发 ttwid；带 ttwid 再请求同一 URL 才返回完整 SSR（160KB+）。
//
// ⚠️ 为什么要跑两次：ttwid 是否下发有随机性 —— 实测单次约 2/3 命中（真实 URLSession 6 轮
// 里 2 轮完全不下发）。单次 warmup 成功率仅 4/6，**前置两次后 6/6**。所以规则里应有
// warmup + warmup2 两步（脚本可原样复用），第三步 detail 才取数据。
//
// ⚠️ UA 必须移动端：桌面 UA 打分享页第二次只有 6.3KB 空壳，iPhone UA 才有 161KB。
// ⚠️ 不要 warmup 首页（www.iesdouyin.com/）：它下发的 __ac_nonce 会让后续分享页反而回
//    6.3KB 空壳（实测 0/3）——warmup 与 detail 必须用同一个分享页 URL。

function dyRiskControl(html) {
  // 只用「风控页面专有」的中文信号。正常分享页也会引用 TTGCaptcha SDK（含 captcha /
  // verifyCenter 字样），把 SDK 引用词当信号会误判所有正常页——故不列英文 SDK 词。
  var signals = ['人机验证', '安全验证', '验证码', '请完成验证', '滑块验证'];
  for (var i = 0; i < signals.length; i++) {
    if (html.indexOf(signals[i]) >= 0) return true;
  }
  return false;
}

// ⚠️ warmup 步必须「静默成功」：引擎按序跑完所有步骤，任一步报 error 就终止 ——
// 若这里对壳页报 error，后面的 detail 步根本不会被执行。
function extract(input) {
  var html = '';
  try { html = (JSON.parse(input).text) || ''; } catch (e) {}
  if (dyRiskControl(html)) return JSON.stringify({ rateLimited: true });
  return JSON.stringify({ warmup: 'ok' });
}

// 抖音分享页 · step2「detail」—— 从 SSR HTML 里抽作品 item。
//
// 前置：step1 已用移动 UA 打过同一 URL，ttwid 已在 HTTPCookieStorage.shared 里，
// 本步（第二次请求）才拿到完整数据。
//
// 数据落点：_ROUTER_DATA.loaderData["note_(id)/page"|"video_(id)/page"]
//             .videoInfoRes.item_list[0]
//   实测同一 ID 走 /share/note/ 与 /share/video/ 返回**完全相同**的 item
//   （desc / author / video.play_addr / cover / duration 全等），故统一走 note 路径。
//
//   desc                      → 标题
//   video.play_addr.url_list  → 视频地址（playwm = 带水印，需换成 play）
//   video.play_addr.uri       → 无水印直链基座（优先，构造 1080p）
//   video.cover.url_list      → 封面
//   images[].url_list[0]      → 图集图片
//
// 图集坑：图集页的 video.play_addr 是 playwm 模板占位视频，吐出去会被引擎判为视频源、
// 不走图片导入。故只要有图片就清空视频地址并显式声明 expectsVideo=false。

function dyRiskControl(html) {
  var signals = ['人机验证', '安全验证', '验证码', '请完成验证', '滑块验证'];
  for (var i = 0; i < signals.length; i++) {
    if (html.indexOf(signals[i]) >= 0) return true;
  }
  return false;
}

// 括号配对抽 JSON（字符串感知：跳过转义与引号内字符）
function dyBalancedJSON(html, from) {
  var s = html.indexOf('{', from);
  if (s < 0) return null;
  var depth = 0, inStr = false, esc = false;
  for (var p = s; p < html.length; p++) {
    var c = html.charAt(p);
    if (esc) { esc = false; continue; }
    if (c === '\\') { esc = true; continue; }
    if (c === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return html.slice(s, p + 1); }
  }
  return null;
}

// 从一个 url 容器（{url_list:[...]} / {urlList:[...]}）取首个地址
function dyFirstURL(node) {
  if (!node || typeof node !== 'object') return '';
  var list = node.url_list || node.urlList || [];
  return (list && list.length && typeof list[0] === 'string') ? list[0] : '';
}

// 单个节点里找 item（兼容视频/图集/嵌套 data 层级，对齐旧原生解析器语义）
function dyItemFromNode(node) {
  if (!node || typeof node !== 'object') return null;
  if (node.videoInfoRes && node.videoInfoRes.item_list && node.videoInfoRes.item_list[0]) {
    return node.videoInfoRes.item_list[0];
  }
  if (node.item_list && node.item_list[0]) return node.item_list[0];
  if (node.aweme_detail && node.aweme_detail.item_list && node.aweme_detail.item_list[0]) {
    return node.aweme_detail.item_list[0];
  }
  var d = node.data;
  if (d && typeof d === 'object') {
    if (d.videoInfoRes && d.videoInfoRes.item_list && d.videoInfoRes.item_list[0]) {
      return d.videoInfoRes.item_list[0];
    }
    if (d.item_list && d.item_list[0]) return d.item_list[0];
    if (d.aweme_detail && d.aweme_detail.item_list && d.aweme_detail.item_list[0]) {
      return d.aweme_detail.item_list[0];
    }
  }
  return null;
}

function dyPickItem(root) {
  var nodes = [];
  var ld = root && root.loaderData;
  if (ld && typeof ld === 'object') {
    for (var k in ld) {
      if (ld[k] && typeof ld[k] === 'object') nodes.push(ld[k]);
    }
  }
  nodes.push(root);
  for (var i = 0; i < nodes.length; i++) {
    var it = dyItemFromNode(nodes[i]);
    if (it) return it;
  }
  return null;
}

function extract(input) {
  var o = {};
  try { o = JSON.parse(input) || {}; } catch (e) { return JSON.stringify({ error: '输入不是合法 JSON' }); }
  var html = o.text || '';
  if (!html) return JSON.stringify({ error: '页面为空' });

  if (dyRiskControl(html)) return JSON.stringify({ rateLimited: true });

  // 壳页（首次请求 / 内容不可访问）没有 item_list，只有「抱歉出错了」文案
  var marker = 'window._ROUTER_DATA';
  var mi = html.indexOf(marker);
  if (mi < 0) {
    return JSON.stringify({ error: '分享页未返回数据（内容可能已删除，或链接无效）' });
  }

  var json = dyBalancedJSON(html, mi);
  if (!json) return JSON.stringify({ error: '_ROUTER_DATA 结构不完整' });

  var root;
  try { root = JSON.parse(json); } catch (e) { return JSON.stringify({ error: '_ROUTER_DATA 解析失败' }); }

  var item = dyPickItem(root);
  if (!item) return JSON.stringify({ error: '分享页未返回作品信息（内容可能已删除，或链接无效）' });

  var title = item.desc || item.title || item.aweme_desc || '';
  if (!title) title = '抖音作品' + (item.aweme_id ? ' ' + item.aweme_id : '');

  // 图集图片
  var images = (item.images && item.images.length) ? item.images : [];
  var imageURLs = [];
  for (var i = 0; i < images.length; i++) {
    var u = dyFirstURL(images[i]);
    if (u) imageURLs.push(u);
  }

  var video = item.video || {};
  // 封面：video.cover → origin_cover（图集无封面时下方用首图兜底）
  var coverURL = dyFirstURL(video.cover) || dyFirstURL(video.origin_cover) || '';

  // 视频地址：优先 play_addr.uri 构造无水印 1080p；否则 url_list[0] 把 playwm 换成 play
  var videoURL = '';
  var playAddr = video.play_addr || video.playAddr || {};
  if (playAddr && typeof playAddr.uri === 'string' && playAddr.uri) {
    videoURL = 'https://www.iesdouyin.com/aweme/v1/play/?video_id=' +
              playAddr.uri + '&ratio=1080p&line=0';
  } else {
    var pu = dyFirstURL(playAddr);
    if (pu) videoURL = pu.replace('playwm', 'play');
  }

  var out = {
    title: title,
    description: title,
    body: title,
    coverURL: coverURL,
    imageURLs: imageURLs,
    videoURL: videoURL
  };

  // 图集优先：有图片就清掉视频地址（图集页自带的 playwm 是占位模板），
  // 并显式声明非视频，否则引擎会把它当视频源、不走图片导入。
  if (imageURLs.length > 0) {
    out.videoURL = '';
    out.expectsVideo = false;
    if (!out.coverURL) out.coverURL = imageURLs[0];
  }

  return JSON.stringify(out);
}

function extract(input) {
    // 小红书解析页面脚本（platformsV2 / fetch.method=http）。
    // 移植自 LinkParser+Xiaohongshu.swift：单次 HTTP 拉页面 HTML，
    // 从 SSR JSON（__SETUP_SERVER_STATE__ / __INITIAL_STATE__）提取笔记数据，
    // meta 兜底；两路全空判限流（限流页输出 rateLimited，引擎抛 PlatformRateLimitedError；其余 error 按 fallbackToLegacy 退通用解析）。
    var ctx = JSON.parse(input);
    var html = ctx.text || "";

    // ---- 与规则包 platforms.xiaohongshu 同源的常量（站点改版时在此热更） ----
    var MARK_SETUP = "window.__SETUP_SERVER_STATE__";
    var MARK_INIT  = "window.__INITIAL_STATE__";
    var NOTE_DATA_PATHS = ["LAUNCHER_SSR_STORE_PAGE_DATA.noteData", "note", "noteWithComments",
        "currentNote", "noteData.data.noteData", "noteData.normalNotePreloadData",
        "noteDetailMap", "global.noteDetailMap", "note.noteDetailMap"];
    var TITLE_FIELDS = ["title", "displayTitle", "display_title"];
    var DESC_FIELDS = ["desc", "description", "body", "content", "text"];
    var STREAM_KEYS = ["h264", "h265"];
    var VIDEO_URL_FIELDS = ["masterUrl", "master_url"];
    var IMAGE_LIST_KEYS = ["imageList", "imagesList", "image_list"];
    var IMAGE_URL_FIELDS = ["urlDefault", "url_default", "url"];
    var COVER_FILE_ID_PREFIX = "https://sns-webpic-qc.xhscdn.com/";
    var MAX_MEDIA = 15;

    // ---- 基础工具（与 Swift 侧 sanitizeJSLiteral / extractBalancedJSON 同逻辑） ----
    function sanitize(s) {
        return s.replace(/\bundefined\b/g, "null")
                .replace(/\bNaN\b/g, "null")
                .replace(/\bInfinity\b/g, "null")
                .replace(/,(\s*[}\]])/g, "$1");
    }
    function balancedJSON(text, marker) {
        var remaining = text;
        if (marker) {
            var idx = remaining.indexOf(marker);
            if (idx === -1) return null;
            remaining = remaining.slice(idx + marker.length);
        }
        var start = remaining.indexOf("{");
        if (start === -1) return null;
        remaining = remaining.slice(start);
        var depth = 0, inStr = false, quote = "\"", escaped = false, end = -1;
        for (var i = 0; i < remaining.length; i++) {
            var ch = remaining.charAt(i);
            if (inStr) {
                if (escaped) { escaped = false; }
                else if (ch === "\\") { escaped = true; }
                else if (ch === quote) { inStr = false; }
            } else {
                if (ch === "{") { depth++; }
                else if (ch === "}") { depth--; if (depth === 0) { end = i; break; } }
                else if (ch === "\"" || ch === "'") { inStr = true; quote = ch; escaped = false; }
            }
        }
        if (end === -1) return null;
        return remaining.slice(0, end + 1);
    }
    function parseDict(s) {
        try {
            var o = JSON.parse(sanitize(s));
            return (o && typeof o === "object" && !(o instanceof Array)) ? o : null;
        } catch (e) { return null; }
    }
    function isDict(v) { return v && typeof v === "object" && !(v instanceof Array); }

    // ---- note 数据定位（与 extractRednoteNoteData 同逻辑，含 noteDetailMap 集合展开） ----
    function candidatesFromPath(root, path) {
        var parts = path.split(".");
        var node = root;
        for (var i = 0; i < parts.length; i++) {
            if (!isDict(node) || !(parts[i] in node)) return [];
            node = node[parts[i]];
        }
        if (!isDict(node)) return [];
        var keys = Object.keys(node);
        if (!keys.length) return [];
        var allDict = true;
        for (var k = 0; k < keys.length; k++) {
            if (!isDict(node[keys[k]])) { allDict = false; break; }
        }
        if (allDict) {
            var out = [];
            for (var k2 = 0; k2 < keys.length; k2++) {
                var entry = node[keys[k2]];
                if (isDict(entry.note)) { out.push(entry.note); }
                else if (entry.title != null || entry.desc != null
                         || entry.imageList != null || entry.imagesList != null) { out.push(entry); }
            }
            return out;
        }
        return [node];
    }
    function extractNoteData(root) {
        var candidates = [];
        for (var i = 0; i < NOTE_DATA_PATHS.length; i++) {
            candidates = candidates.concat(candidatesFromPath(root, NOTE_DATA_PATHS[i]));
        }
        for (var j = 0; j < candidates.length; j++) {
            var c = candidates[j];
            if (c.title != null || c.desc != null || c.imageList != null || c.imagesList != null) return c;
        }
        return candidates.length ? candidates[0] : root;
    }

    // ---- 字段提取（与 extractRednoteTitle / extractRednoteBody 等同逻辑） ----
    function extractTitle(nd, root) {
        var sources = [nd, root, (root && isDict(root.userPageData)) ? root.userPageData : {}];
        for (var s = 0; s < sources.length; s++) {
            for (var k = 0; k < TITLE_FIELDS.length; k++) {
                var v = sources[s][TITLE_FIELDS[k]];
                if (typeof v === "string" && v) return v;
            }
        }
        return "";
    }
    function extractBody(nd, fallbackTitle) {
        for (var k = 0; k < DESC_FIELDS.length; k++) {
            var v = nd[DESC_FIELDS[k]];
            if (typeof v === "string" && v) return v;
        }
        if (nd.itemList instanceof Array) {
            for (var i = 0; i < nd.itemList.length; i++) {
                var item = nd.itemList[i] || {};
                if (typeof item.content === "string" && item.content) return item.content;
                if (typeof item.desc === "string" && item.desc) return item.desc;
            }
        }
        return fallbackTitle;
    }
    function extractVideo(nd) {
        var video = nd.video;
        if (!isDict(video)) return null;
        var media = isDict(video.media) ? video.media : {};
        var stream = isDict(media.stream) ? media.stream : {};
        var streams = [];
        for (var i = 0; i < STREAM_KEYS.length; i++) {
            var arr = stream[STREAM_KEYS[i]];
            if (arr instanceof Array) streams = streams.concat(arr);
        }
        if (streams.length) {
            for (var j = 0; j < VIDEO_URL_FIELDS.length; j++) {
                var v = streams[0][VIDEO_URL_FIELDS[j]];
                if (typeof v === "string" && v) return v;
            }
        }
        if (typeof video.mediaV2 === "string") {
            var m2 = parseDict(video.mediaV2);
            if (m2) {
                for (var j2 = 0; j2 < VIDEO_URL_FIELDS.length; j2++) {
                    var v2 = m2[VIDEO_URL_FIELDS[j2]];
                    if (typeof v2 === "string" && v2) return v2;
                }
            }
            return null;
        }
        // 降级：media.video 直取（SetupState 路径的兜底分支）
        if (isDict(media.video)) {
            var mv = media.video.url || media.video.masterUrl;
            if (typeof mv === "string" && mv) return mv;
        }
        return null;
    }
    function extractImages(nd) {
        var list = null;
        for (var k = 0; k < IMAGE_LIST_KEYS.length; k++) {
            if (nd[IMAGE_LIST_KEYS[k]] instanceof Array) { list = nd[IMAGE_LIST_KEYS[k]]; break; }
        }
        if (!list) return [];
        var out = [];
        for (var i = 0; i < list.length && out.length < MAX_MEDIA; i++) {
            var img = list[i] || {};
            var found = null;
            for (var f = 0; f < IMAGE_URL_FIELDS.length; f++) {
                var u = img[IMAGE_URL_FIELDS[f]];
                if (typeof u === "string" && u) { found = u; break; }
            }
            if (!found) {
                var infos = img.infoList || img.info_list;
                if (infos instanceof Array && infos.length && typeof infos[0].url === "string") {
                    found = infos[0].url;
                }
            }
            if (found) out.push(found.indexOf("http://") === 0 ? found.replace("http://", "https://") : found);
        }
        return out;
    }

    // ---- meta 兜底（对应 extractFromHTML 的 meta 部分） ----
    function decodeHTML(s) {
        return String(s)
            .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
            .replace(/&quot;/g, "\"").replace(/&#39;/g, "'").replace(/&nbsp;/g, " ");
    }
    var metaCache = null;
    function readMeta(names) {
        if (!metaCache) {
            metaCache = {};
            var tags = html.match(/<meta\b[^>]*>/gi) || [];
            for (var i = 0; i < tags.length; i++) {
                var nm = tags[i].match(/(?:property|name)=["\']([^"\']+)["\']/i);
                var cm = tags[i].match(/content=["\']([^"\']*)["\']/i);
                if (nm && cm && !(nm[1] in metaCache)) metaCache[nm[1]] = decodeHTML(cm[1]);
            }
        }
        for (var j = 0; j < names.length; j++) {
            var v = metaCache[names[j]];
            if (v) return v;
        }
        return "";
    }

    // ---- 两条 SSR 路径 ----
    function parseSetup() {
        var s = balancedJSON(html, MARK_SETUP);
        if (!s) return null;
        var data = parseDict(s);
        if (!data) return null;
        var launcher = data.LAUNCHER_SSR_STORE_PAGE_DATA;
        if (!isDict(launcher) || !isDict(launcher.noteData)) return null;
        var nd = launcher.noteData;
        var title = extractTitle(nd, data);
        var desc = extractBody(nd, title);
        var type = nd.type || "";
        var videoURL = null, imageURLs = [], coverURL = null;
        if (type === "video") {
            videoURL = extractVideo(nd);
            if (isDict(nd.cover) && typeof nd.cover.fileId === "string" && nd.cover.fileId) {
                coverURL = COVER_FILE_ID_PREFIX + nd.cover.fileId + "?imageView2/format/jpg";
            }
        } else {
            imageURLs = extractImages(nd);
        }
        return { title: title, description: desc, coverURL: coverURL, imageURLs: imageURLs, videoURL: videoURL };
    }
    function parseInit() {
        var s = balancedJSON(html, MARK_INIT);
        if (!s) return null;
        var data = parseDict(s);
        if (!data) return null;
        var nd = extractNoteData(data);
        var title = extractTitle(nd, data);
        var body = extractBody(nd, title);
        var type = nd.type || "";
        var videoURL = extractVideo(nd);
        var coverURL = null;
        if (isDict(nd.cover)) {
            var cu = nd.cover.urlDefault || nd.cover.url_default;
            if (typeof cu === "string" && cu) coverURL = cu;
        }
        var imageURLs = extractImages(nd);
        if (type === "video") {
            // 视频笔记的 imageList 是预览帧，不当地图集；cover 缺失用首帧
            if (!coverURL && imageURLs.length) coverURL = imageURLs[0];
            imageURLs = [];
        }
        return { title: title, description: body, coverURL: coverURL, imageURLs: imageURLs, videoURL: videoURL };
    }

    var setupRes = parseSetup();
    var initRes = parseInit();
    var primary = setupRes || initRes;
    var other = setupRes ? initRes : null;

    function pick(a, b, c) { return a || b || c || ""; }

    if (primary) {
        var metaTitle = readMeta(["og:title", "twitter:title"]);
        var metaCover = readMeta(["og:image", "twitter:image"]);
        var out = {
            title: pick(primary.title, other ? other.title : "", metaTitle),
            description: pick(primary.description, other ? other.description : "", readMeta(["og:description"])),
            body: pick(primary.description, other ? other.description : ""),
            coverURL: pick(primary.coverURL, other ? other.coverURL : "", metaCover),
            videoURL: primary.videoURL || (other ? other.videoURL : "") || readMeta(["og:video", "og:video:url", "og:video:secure_url"]),
            imageURLs: primary.imageURLs.length ? primary.imageURLs : (other && other.imageURLs.length ? other.imageURLs : [])
        };
        // 视频笔记保留封面、清图集的语义已在各路径内处理；这里只补 meta 封面兜底
        if (out.videoURL && !out.coverURL && metaCover) out.coverURL = metaCover;
        if (!out.title) return { rateLimited: "true", error: "ssr 命中但标题为空（疑似反爬精简页）" };
        return JSON.stringify(out);
    }

    // 两条 SSR 路径都没命中 → meta 兜底；meta 也没媒体则判限流，交回旧解析器
    var mTitle = readMeta(["og:title", "twitter:title"]);
    var mDesc = readMeta(["og:description", "twitter:description", "description"]);
    var mCover = readMeta(["og:image", "twitter:image"]);
    var mVideo = readMeta(["og:video", "og:video:url", "og:video:secure_url"]);
    var hasUseful = mTitle || mDesc || mCover || mVideo;
    if (!hasUseful) {
        return { rateLimited: "true", error: "两个 SSR marker 均未命中且 meta 无数据（疑似限流精简页）" };
    }
    return JSON.stringify({
        title: mTitle,
        description: mDesc,
        body: mDesc,
        coverURL: mCover,
        videoURL: mVideo,
        imageURLs: (mCover && !mVideo) ? [mCover] : []
    });
}

// 芒果TV platformsV2 插件 · Step0: 专题/合集页探测
// 背景：/topic/{tid}.html 是合集页（内含多集 /b/{album}/{vid}.html），idPattern 抽到的是 topic id 而非视频 id，
// 直接调 player/video 会 code=30001 失败、退回旧解析器落成图集。本步从专题页 HTML 提取首个
// /b/{album}/{vid}.html 的 vid 覆盖 vars['id']，后续 info/source/atcl 即走视频解析。
// 单视频页（/b/{album}/{vid}.html）url 不含 /topic/ → 不重写，沿用 idPattern 已抽对的 vid。
function extract(input) {
    var o = JSON.parse(input);
    var url = o.url || '';
    if (url.indexOf('/topic/') === -1) return JSON.stringify({});
    var text = o.text || '';
    var m = text.match(/\/b\/(\d+)\/(\d+)\.html/);
    if (!m) return JSON.stringify({ error: '未从专题页提取到视频链接' });
    return JSON.stringify({ id: m[2] });
}

// 芒果TV platformsV2 插件 · http 步骤脚本（3 步）
// 链路：player/video(info+pm2) → getSource(stream 列表) → atcl(m3u8 直链)
// tk2 签名实测宽松（只验 base64 格式，不验内容/时效，2026-09-11）→ urlTemplate 写死静态串。
// 产物 = HLS m3u8（未加密 TS 分片）→ 依赖下载器 HLS 分支（LinkParser+Download）拼接 .ts。
// ES5 纯计算，无 window/document 依赖（JSC 沙箱契约：进去一串字出来一串字）。

// ---- Step1: player/video → title/cover/duration/pm2 ----
function extract(input) {
    var o = JSON.parse(input);
    var api = JSON.parse(o.text);
    if (String(api.code) !== '200') {
        return JSON.stringify({ error: '芒果 player/video code=' + api.code + ' ' + (api.msg || '') });
    }
    var data = api.data || {};
    var info = data.info || {};
    var pm2 = (data.atc || {}).pm2;
    if (!pm2) return JSON.stringify({ error: '无 pm2（可能 VIP 专享或地区限制）' });
    var title = String(info.title || '').replace(/^\s+|\s+$/g, '');
    return JSON.stringify({
        title: title,
        description: info.desc || '',
        coverURL: info.thumb || '',
        duration: info.duration || '',
        pm2: pm2
    });
}

// 芒果TV platformsV2 插件 · Step2: getSource → 选最高码率可用流 → 拼 atcl URL
function extract(input) {
    var api = JSON.parse(JSON.parse(input).text);
    if (String(api.code) !== '200') {
        return JSON.stringify({ error: '芒果 getSource code=' + api.code + ' ' + (api.msg || '') });
    }
    var data = api.data || {};
    var domains = data.stream_domain || [];
    var streams = data.stream || [];
    if (!domains.length || !streams.length) return JSON.stringify({ error: '无可用视频流' });
    // 选 filebitrate 最高且 url 非空的流（1080P 常为 VIP 空地址，自动跳过）
    var best = null;
    for (var i = 0; i < streams.length; i++) {
        var s = streams[i];
        if (!s.url) continue;
        var br = parseInt(s.filebitrate, 10) || 0;
        if (!best || br > best.br) {
            best = { url: s.url, br: br, name: s.name || s.standardName || s.barName || '' };
        }
    }
    if (!best) return JSON.stringify({ error: '所有清晰度均无地址（可能 VIP 专享）' });
    return JSON.stringify({
        m3u8ApiURL: domains[0] + best.url,
        quality: best.name
    });
}

// 芒果TV platformsV2 插件 · Step3: atcl → m3u8 直链（videoURL 交下载器 HLS 分支）
function extract(input) {
    var o = JSON.parse(input);
    var api = JSON.parse(o.text);
    var info = (api.data && api.data.info) || api.info || '';
    if (typeof info !== 'string' || info.indexOf('http') !== 0) {
        return JSON.stringify({ error: '未取到 m3u8 地址' });
    }
    // 附带校验形态：必须是 .m3u8 直链（下载器按此识别 HLS 分支）
    if (info.indexOf('.m3u8') === -1) {
        return JSON.stringify({ error: '流地址不是 m3u8（结构可能已改版）' });
    }
    return JSON.stringify({ videoURL: info });
}

// 搜狐视频 step1：页面 HTML 提取 vid（tv.sohu.com / my.tv.sohu.com SSR 页）
// 输入: JSON 字符串 '{"text":页面HTML,"url":页面URL}'  输出: {vid}
// 页面 URL 里不含 vid（v/xxx.html 是 base64、nXXXX.shtml 是 CMS 编号），
// vid 只在 SSR 源码 `var vid="3155125"` 里。
function extract(input) {
    var p = {};
    try { p = JSON.parse(input); } catch (e) { p = {}; }
    var text = String(p.text || '');
    var url = String(p.url || '');

    // 主路径：var vid="数字"（yt-dlp 同款正则，宽松空白）
    var m = text.match(/var\s+vid\s*=?\s*["'](\d+)["']/);
    if (!m) {
        // 候选 1：sohu JSON 块 "vid":"数字" 或 "vid":数字
        m = text.match(/"vid"\s*:\s*"?(\d{4,})"?/);
    }
    if (!m) {
        return JSON.stringify({ error: '页面源码里没有 vid（形态可能已改版或为限流页） url=' + url.slice(0, 80) });
    }
    return JSON.stringify({ vid: m[1] });
}

// 搜狐视频 step2：videonew.do 播放元数据 → videoPlan（分片换链计划）
// 输入: {text: videonew.do JSON, url: API地址}  输出: title/coverURL/duration/videoPlan
// 端点说明（2026-09-11 定稿）：my.tv.sohu.com/play/videonew.do 对官方版权视频
// （tv.sohu.com/nXXX.shtml）与用户上传视频（us/UID/VID.shtml）都返回完整分片；
// 旧端点 hot.vrs.sohu.com/vrs_flash.action 对用户上传视频返回 data=null（status=6），
// 只能覆盖官方片，故废弃。
// videoPlan 协议（引擎 LinkParser+Segments.swift 消费）：
//   { type: "chainedSegments", format: "mp4"|"ts",
//     segments: [{fetchURL: <GET 后返回 JSON>, resultField: <取哪个字段当直链>}] }
// 换链协议（allot ?prot=9&file=&new= 与字段名 url）在此声明，引擎只做通用执行。
function extract(input) {
    var p = '';
    try { p = JSON.parse(input).text || ''; } catch (e) { p = ''; }
    var d;
    try { d = JSON.parse(p); }
    catch (e) { return JSON.stringify({ error: 'videonew.do 响应不是 JSON: ' + e.message }); }

    if (d.play !== 1) {
        var st = (d.status != null) ? (' status=' + d.status) : '';
        return JSON.stringify({ error: '接口判不可播 (play=' + d.play + st + ')' });
    }
    // 付费内容 fail loud：试看片段下载出来是半截废素材
    if (Number(d.fee) > 0 || Number(d.tvfee) > 0 || d.is_member_play === 1) {
        return JSON.stringify({ error: 'VIP/付费内容，暂不支持（fee=' + d.fee + ' tvfee=' + d.tvfee + '）' });
    }

    var data = d.data || {};
    var allot = String(d.allot || data.allot || '');
    if (!allot) { return JSON.stringify({ error: '响应缺 allot（换链服务器地址）' }); }

    // 用户上传视频只有 mp4PlayUrl（完整 URL），官方视频是 clipsURL（相对路径）——逐片取「先到者」
    var clips = data.clipsURL || [];
    var mp4s = data.mp4PlayUrl || [];
    var su = data.su || [];
    var blocks = Number(data.totalBlocks) || 0;
    if (!blocks || !su.length) {
        return JSON.stringify({ error: '分片数据缺失 (totalBlocks=' + blocks
            + ' clipsURL=' + clips.length + ' mp4PlayUrl=' + mp4s.length + ' su=' + su.length + ')' });
    }

    var segments = [];
    for (var i = 0; i < blocks; i++) {
        var file = clips[i] || mp4s[i];
        if (!file || !su[i]) {
            return JSON.stringify({ error: '第' + i + '片数据不齐 (file=' + (file ? '有' : '无') + ' su=' + (su[i] ? '有' : '无') + ')' });
        }
        segments.push({
            fetchURL: 'https://' + allot + '/?prot=9&file=' + file + '&new=' + su[i] + '&prod=h5n&rb=1',
            resultField: 'url'
        });
    }

    var title = String(data.tvName || d.title || '').trim();
    if (!title) { return JSON.stringify({ error: '标题缺失 (tvName 为空)' }); }

    var out = {
        title: title,
        coverURL: String(data.coverImg || '') || undefined,
        duration: Number(data.totalDuration) > 0 ? Number(data.totalDuration) : undefined,
        videoPlan: { type: 'chainedSegments', format: 'mp4', segments: segments }
    };
    return JSON.stringify(out);
}

// YouTube 解析脚本（platformsV2 / fetch.method=post / innertube ANDROID client）
// 契约：extract(input)，input = JSON.stringify({text: API响应, url: 最终URL})
// 策略（2026-09-11 实测）：ANDROID client POST youtubei/v1/player 仍返回带 URL 的
// progressive 流（itag 18=360p mp4 音视频合一）；web/iOS client 已被 SABR 剥离 URL。
// 引擎无音视频合成能力，只挑 progressive（formats 数组）里的 video/mp4。
function extract(input) {
    var inp = JSON.parse(input);
    var text = inp.text || '';
    var out = {};
    try {
        var d = JSON.parse(text);
        var ps = d.playabilityStatus || {};
        if (ps.status && ps.status !== 'OK' && ps.status !== 'LIVE_STREAM_OFFLINE') {
            out.error = 'youtube playability ' + ps.status + ': ' + String(ps.reason || '');
            return JSON.stringify(out);
        }
        var sd = d.streamingData || {};
        var formats = sd.formats || [];
        var best = null, bestH = -1;
        for (var i = 0; i < formats.length; i++) {
            var f = formats[i];
            var mime = String(f.mimeType || '');
            if (mime.indexOf('video/mp4') !== 0) continue;
            if (!f.url) continue;
            var h = parseInt(f.height, 10) || 0;
            if (h > bestH) { bestH = h; best = f; }
        }
        if (!best) {
            out.error = 'youtube: no progressive mp4 (SABR-only?), formats=' + formats.length +
                ' adaptive=' + (sd.adaptiveFormats || []).length;
            return JSON.stringify(out);
        }
        out.videoURL = best.url;
        var vd = d.videoDetails || {};
        out.title = vd.title || 'YouTube 视频';
        if (vd.lengthSeconds) out.duration = vd.lengthSeconds;
        if (vd.author) out.author = vd.author;
    } catch (e) {
        out.error = 'youtube parse: ' + e.message;
    }
    return JSON.stringify(out);
}

// TikTok 解析脚本（platformsV2 / fetch.method=http / SSR universal data）
// 契约：extract(input)，input = JSON.stringify({text: 页面HTML, url: 最终URL})
// 策略（yt-dlp 2026-09 实锤路径）：页面 SSR 的 __UNIVERSAL_DATA_FOR_REHYDRATION__
// → __DEFAULT_SCOPE__["webapp.video-detail"].itemInfo.itemStruct.video.playAddr 纯直链。
// 注意：HK 出口会被 302 到 /hk/about（TikTok 不服务香港），marker 缺失时如实报错。
function extract(input) {
    var inp = JSON.parse(input);
    var text = inp.text || '';
    var out = {};
    var m = /<script[^>]+\bid="__UNIVERSAL_DATA_FOR_REHYDRATION__"[^>]*>([\s\S]*?)<\/script>/.exec(text);
    if (!m) {
        out.error = 'tiktok: universal-data marker not found (region redirect or verify page)';
        return JSON.stringify(out);
    }
    try {
        var d = JSON.parse(m[1]);
        var scope = d.__DEFAULT_SCOPE__ || {};
        var detail = scope['webapp.video-detail'] || {};
        var item = ((detail.itemInfo || {}).itemStruct) || {};
        var v = item.video || {};
        var url = v.playAddr || '';
        if (!url) {
            out.error = 'tiktok: no playAddr' + (item.id ? '' : ' (itemStruct empty — verify/captcha page)');
            return JSON.stringify(out);
        }
        out.videoURL = url;
        out.title = item.desc || (item.author && item.author.nickname) || 'TikTok 视频';
        if (item.author && item.author.uniqueId) out.author = item.author.uniqueId;
        if (v.duration) out.duration = v.duration;
    } catch (e) {
        out.error = 'tiktok parse: ' + e.message;
    }
    return JSON.stringify(out);
}

(function() {
    // Instagram 解析页面脚本（platformsV2 / fetch.method=webview）。
    // 职责：hook XHR/fetch 拦 /api/graphql 响应，从 data.xig_polaris_media（路径不固定，深搜）
    // 挖 video_versions（type 101 = xpv_progressive mp4 直链，实测无 Referer 可下），
    // 经 pluginResult 桥回传。兜底：页面 <video> / og:video meta。
    // 侦察实锤（2026-09-11）：未登录 curl 拿到的 SSR 已无帖子数据；真浏览器里页面自己
    // POST /api/graphql（PolarisPostRootQuery），响应含 video_versions mp4 直链。

    if (window.__igPluginInjected) return;
    window.__igPluginInjected = true;

    var logCount = 0;
    function postLog(msg) {
        if (logCount >= 80) return;
        logCount++;
        try { window.webkit.messageHandlers.pluginLog.postMessage(String(msg)); } catch (e) {}
    }
    function postResult(obj) {
        try { window.webkit.messageHandlers.pluginResult.postMessage(JSON.stringify(obj)); } catch (e) {}
    }

    var shortId = (window.location.pathname.match(/\/(?:p|reel|tv)\/([^\/?#]+)/) || [])[1] || 'null';
    postLog('v1.4.2 url=' + window.location.pathname.slice(0, 80) + ' shortcode=' + shortId);

    if (window.__igDone) return;
    window.__igDone = false;
    var captured = [];

    // ---- 深搜：在任意嵌套对象里找 video_versions 数组，挑 width 最大的 mp4 ----
    function findVideoVersions(node, depth) {
        if (!node || typeof node !== 'object' || depth > 14) return null;
        if (Object.prototype.toString.call(node) === '[object Array]') {
            for (var i = 0; i < node.length; i++) {
                var r = findVideoVersions(node[i], depth + 1);
                if (r) return r;
            }
            return null;
        }
        var vv = node.video_versions;
        if (Object.prototype.toString.call(vv) === '[object Array]' && vv.length > 0) return vv;
        for (var k in node) {
            if (!Object.prototype.hasOwnProperty.call(node, k)) continue;
            var r2 = findVideoVersions(node[k], depth + 1);
            if (r2) return r2;
        }
        return null;
    }

    function pickBestMp4(vv) {
        var best = null, bestW = -1;
        for (var i = 0; i < vv.length; i++) {
            var v = vv[i] || {};
            var u = String(v.url || '');
            if (!u || u.indexOf('.mp4') === -1) continue;   // 首元素常是封面帧 jpg
            var w = parseInt(v.width, 10) || 0;
            if (w > bestW) { bestW = w; best = u; }
        }
        return best;
    }

    // 标题：xig_polaris_media.caption.text 或 title 字段（深搜第一个命中的）
    function findCaption(node, depth) {
        if (!node || typeof node !== 'object' || depth > 14) return '';
        if (Object.prototype.toString.call(node) === '[object Array]') {
            for (var i = 0; i < node.length; i++) {
                var r = findCaption(node[i], depth + 1);
                if (r) return r;
            }
            return '';
        }
        var cap = node.caption;
        if (cap && typeof cap === 'object' && typeof cap.text === 'string' && cap.text) return cap.text;
        if (typeof node.title === 'string' && node.title) return node.title;
        for (var k in node) {
            if (!Object.prototype.hasOwnProperty.call(node, k)) continue;
            var r2 = findCaption(node[k], depth + 1);
            if (r2) return r2;
        }
        return '';
    }

    function tryEmit(reason) {
        if (window.__igDone) return true;
        for (var i = 0; i < captured.length; i++) {
            var text = captured[i];
            var d = null;
            try { d = JSON.parse(text); } catch (e) { continue; }
            var vv = findVideoVersions(d, 0);
            if (!vv) continue;
            var mp4 = pickBestMp4(vv);
            if (!mp4) continue;
            var title = findCaption(d, 0) || ('Instagram ' + shortId);
            window.__igDone = true;
            postLog('EMIT via ' + reason + ' vv=' + vv.length);
            postResult({ title: String(title).slice(0, 300), videoURL: mp4 });
            return true;
        }
        return false;
    }

    function inspectBody(text, url) {
        if (window.__igDone) return;
        var u = String(url || '');
        if (u.indexOf('/api/graphql') === -1) return;
        captured.push(text);
        if (captured.length <= 6) {
            var s = String(text);
            postLog('RESP ' + u.slice(0, 40) + ' len=' + s.length +
                ' vv=' + (s.indexOf('video_versions') !== -1) +
                ' pm=' + (s.indexOf('xig_polaris_media') !== -1));
        }
        tryEmit('xhr');
    }

    // ---- hook XHR + fetch（IG graphql 走 XHR；保险双 hook）----
    var oo = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function(m, u) {
        this.__igU = String(u);
        return oo.apply(this, arguments);
    };
    var os = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.send = function() {
        var xhr = this;
        if (xhr.__igU && xhr.__igU.indexOf('/api/graphql') !== -1) {
            xhr.addEventListener('load', function() {
                try { inspectBody(String(xhr.responseText), xhr.__igU); } catch (e) { postLog('xhr err ' + e.message); }
            });
        }
        return os.apply(this, arguments);
    };
    if (window.fetch) {
        var of = window.fetch;
        window.fetch = function(u) {
            var p = of.apply(this, arguments);
            try {
                if (String(u).indexOf('/api/graphql') !== -1) {
                    p.then(function(r) { r.clone().text().then(function(t) { inspectBody(t, u); }).catch(function() {}); }).catch(function() {});
                }
            } catch (e) {}
            return p;
        };
    }

    // ---- 兜底1：页面已有数据（SPA 二次进入时 hook 晚了）→ 全局搜 JSON 字符串 ----
    // ---- 兜底2：<video> 元素 / og:video meta ----
    function domFallback() {
        if (window.__igDone) return;
        var vid = document.querySelector('video[src]');
        if (vid && vid.src && vid.src.indexOf('http') === 0) {
            var og = document.querySelector('meta[property="og:title"]');
            window.__igDone = true;
            postLog('EMIT via dom-video');
            postResult({ title: (og && og.content) || ('Instagram ' + shortId), videoURL: vid.src });
            return;
        }
        var meta = document.querySelector('meta[property="og:video"], meta[property="og:video:url"]');
        if (meta && meta.content && meta.content.indexOf('.mp4') !== -1) {
            window.__igDone = true;
            postLog('EMIT via og:video');
            postResult({ title: 'Instagram ' + shortId, videoURL: meta.content });
        }
    }

    // 多轮兜底（graphql 响应晚到 / SPA 路由慢）
    var rounds = [1500, 3500, 6000, 9000];
    for (var i = 0; i < rounds.length; i++) {
        (function(ms, idx) {
            setTimeout(function() {
                if (window.__igDone) return;
                tryEmit('round' + idx);
                domFallback();
                if (!window.__igDone && idx === rounds.length - 1) {
                    postLog('GIVEUP captured=' + captured.length);
                }
            }, ms);
        })(rounds[i], i);
    }
})();

// TED 插件: talk 页 → og 元数据 + __NEXT_DATA__ 里的 HLS master 地址。
// TED 页 og:video:url 是 embed 网页而非视频文件，视频唯一通道是 hls.ted.com 的 HLS。
// master 直吐 videoURL：最高码率变体挑选与音轨下载合成由引擎 HLS 层原生完成
// （TED 是音视频分离打包，无声问题修复于 2026-09-25，见 docs/ted解析方案验证-2026-09-25.md）。
function extract(input) {
    var text = JSON.parse(input).text || '';
    function meta(prop) {
        var m = new RegExp('<meta[^>]*property="' + prop + '"[^>]*content="([^"]*)"', 'i').exec(text)
             || new RegExp('<meta[^>]*content="([^"]*)"[^>]*property="' + prop + '"', 'i').exec(text);
        return m ? m[1] : '';
    }
    function decode(s) {
        return s.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
                .replace(/&lt;/g, '<').replace(/&gt;/g, '>');
    }
    var title = decode(meta('og:title'));
    if (!title) { return JSON.stringify({ error: 'ted: og:title 缺失（非 talk 页或已改版）' }); }
    var hls = /"hlsUrl"\s*:\s*"(https:\/\/hls\.ted\.com[^"]+?\.m3u8[^"]*)"/.exec(text);
    if (!hls) { return JSON.stringify({ error: 'ted: hlsUrl 缺失（页面结构可能已改版）' }); }
    return JSON.stringify({
        title:       title,
        description: decode(meta('og:description')),
        coverURL:    decode(meta('og:image')),
        videoURL:    hls[1].replace(/\\u0026/g, '&')
    });
}

// 微信公众号插件（webview 步骤）：文章页在离屏 WKWebView 内渲染后抽取字段，
// 经固定桥 pluginResult 回传字段字典（与 http 步骤脚本输出同形）。
//
// 为什么用 webview 而不是 http：公众号文章是服务端渲染完整 HTML（实测 3.5MB+），
// http 步骤要把整页塞给 JSC 脚本，会撞 RuleScriptRunner 的 2MB 输入上限
// （2026-09-30 实测「输入过大，已中止」）。webview 里脚本跑在页面上下文，
// 在页面里直接抽 js_content，只回传抽好的几 KB 结果，天然绕开该闸。
//
// 注入时机是 document start（SSR 正文也在初始 HTML 里），用轮询等 DOM 解析到位：
// 每拍先看 js_content 在不在，不在再看风控/删除页话术（fail fast，不等超时）。
// 桥接契约见 RulePluginWebviewRunner.swift 头注释：pluginResult / pluginLog，只信主帧。
(function () {
    function post(obj) {
        try { window.webkit.messageHandlers.pluginResult.postMessage(JSON.stringify(obj)); } catch (e) { }
    }
    function log(m) {
        try { window.webkit.messageHandlers.pluginLog.postMessage(String(m)); } catch (e) { }
    }

    var POLL_MS = 300;
    var POLL_MAX = 60;  // ≈18s 后放弃并报错，须小于插件 timeout（35s）

    var BLOCK = 'p,section,div,h1,h2,h3,h4,h5,h6,li,blockquote,pre,td,th';

    function metaContent(prop) {
        var m = document.querySelector('meta[property="' + prop + '"]');
        return m ? (m.getAttribute('content') || '') : '';
    }

    // 正文抽取：只收「叶子块」（内部无块级子元素的块级元素），文本用 textContent 而非
    // innerText——公众号正文初始 visibility:hidden、由页面 JS 渐次显示（2026-09-30 离屏
    // webview 实测：元素已在 DOM、textContent=3704 时 innerText 仍≈空），innerText 依赖
    // 渲染态会抽到空；DOM 结构 + textContent 不依赖渲染。叶子由后代叶子代表，避免父子
    // 重复成段；块间空行与通用解析 cleanText 段落语义一致（2026-09-28 起）。
    function leafText(el) {
        if (!el.querySelector('br')) { return el.textContent || ''; }
        // 含 <br> 的叶子：子节点遍历还原换行（textContent 会丢掉 br 的分行）
        var parts = [];
        (function walk(n) {
            for (var c = n.firstChild; c; c = c.nextSibling) {
                if (c.nodeType === 3) { parts.push((c.nodeValue || '').replace(/\s+/g, ' ')); }
                else if (c.nodeType === 1) {
                    if (c.tagName === 'BR') { parts.push('\n'); } else { walk(c); }
                }
            }
        })(el);
        return parts.join('').replace(/ \n /g, '\n');
    }

    function paragraphs(root) {
        var out = [];
        var all = root.querySelectorAll(BLOCK);
        for (var i = 0; i < all.length; i++) {
            var el = all[i];
            if (el.querySelector(BLOCK)) { continue; }
            var t = leafText(el).replace(/[ \t\u00A0\u3000]+/g, ' ').trim();
            if (t) { out.push(t); }
        }
        if (!out.length) {
            // 没有任何块级元素（极端）→ 整块 textContent 按行拆
            var raw = (root.textContent || '').split(/\n/);
            for (var j = 0; j < raw.length; j++) {
                var line = raw[j].replace(/[ \t\u00A0\u3000]+/g, ' ').trim();
                if (line) { out.push(line); }
            }
        }
        return out.join('\n\n');
    }

    function pageText() {
        return (document.body && document.body.innerText) || '';
    }

    function extractNow() {
        var root = document.getElementById('js_content');
        if (!root) {
            var text = pageText();
            if (text.indexOf('环境异常') !== -1 || text.indexOf('操作频繁') !== -1) {
                post({ error: 'weixin: 触发风控验证页', rateLimited: true });
                return true;
            }
            if (text.indexOf('该内容已被发布者删除') !== -1 || text.indexOf('此内容因违规无法查看') !== -1
                || text.indexOf('已停止访问该网页') !== -1) {
                post({ error: 'weixin: 文章已被删除或因违规无法查看' });
                return true;
            }
            var host = (window.location && window.location.host) || '';
            if (host && host !== 'mp.weixin.qq.com') {
                post({ error: 'weixin: 落在了非文章页（' + host + '）' });
                return true;
            }
            return false;  // 继续等（SSR 正文很快出现）
        }

        var title = metaContent('og:title');
        if (!title) {
            var h1 = document.querySelector('h1');
            title = h1 ? (h1.textContent || '').trim() : '';
        }
        if (!title) {
            post({ error: 'weixin: 标题缺失（页面已改版）' });
            return true;
        }

        var body = paragraphs(root);
        if (!body) {
            post({ error: 'weixin: js_content 为空（可能被折叠或已改版）' });
            return true;
        }
        // 与通用解析 MAX_TEXT_LENGTH(10000) 对齐
        if (body.length > 10000) { body = body.substring(0, 10000); }

        var out = {
            title: title,
            description: metaContent('og:description'),
            coverURL: metaContent('og:image'),
            body: body,
            textOnly: true
        };

        // 内容图：data-src 懒加载（下载走 httpPolicy refererMode=none——mmbiz 外站
        // Referer 会被换成占位图，2026-09-30 实测）；无内容图时封面并入 imageURLs
        // 过现有客户端的完整性闸门（热更即全量生效，见 2.0.7 changelog）
        var imgs = [];
        var imgs0 = root.querySelectorAll('img[data-src]');
        for (var k = 0; k < imgs0.length && imgs.length < 30; k++) {
            var u = imgs0[k].getAttribute('data-src') || '';
            if (u.indexOf('mmbiz.qpic.cn') !== -1 && imgs.indexOf(u) === -1) { imgs.push(u); }
        }
        if (imgs.length) { out.imageURLs = imgs; }
        else if (out.coverURL) { out.imageURLs = [out.coverURL]; }

        post(out);
        return true;
    }

    var tries = 0;
    var timer = setInterval(function () {
        tries += 1;
        var done = false;
        try { done = extractNow(); } catch (e) { log('抽取异常: ' + e); }
        if (done || tries >= POLL_MAX) {
            clearInterval(timer);
            if (!done) {
                post({ error: 'weixin: 未等到正文容器（' + tries + ' 次轮询，可能风控或已改版）' });
            }
        }
    }, POLL_MS);
})();

// GitHub Gist 插件：gists API 响应的 files 是「文件名为键」的内联字典，正文无需二次取 raw。
// 取第一个有内容的文件；超大文件会被 GitHub 标记 truncated（content 可能缺失），跳过换下一个。
// 标题优先用 description（常空则退文件名），换行压平、限 120 字。
// 状态码：新引擎 passNon2xx 时可见（403=限流/404=不存在），老引擎非 2xx 不进脚本。
function extract(input) {
    var d = JSON.parse(input);
    var status = d.status || 200;
    function J(o) { return JSON.stringify(o); }
    function err(m) { return J({ error: m }); }
    if (status < 200 || status >= 300) {
        var msg = '';
        try { msg = (JSON.parse(d.text || '{}') || {}).message || ''; } catch (e) { }
        if (status === 403 && /rate limit/i.test(msg)) {
            return J({ error: 'gist: API 限流', rateLimited: true });
        }
        if (status === 404) { return err('gist: 不存在该 Gist（或已删除/为私有）'); }
        return err('gist: 接口返回 HTTP ' + status);
    }
    var api;
    try { api = JSON.parse(d.text || ''); } catch (e) { return err('gist: 接口响应不是 JSON'); }
    var files = api.files || {};
    var first = null, firstKey = '', count = 0;
    for (var k in files) {
        if (!Object.prototype.hasOwnProperty.call(files, k)) { continue; }
        count += 1;
        var f = files[k] || {};
        if (first === null && (f.content || '') !== '') { first = f; firstKey = k; }
    }
    if (!first) { return err(count ? 'gist: 文件均无内联内容（可能超大被截断）' : 'gist: 响应中没有文件'); }
    var body = first.content;
    if (body.length > 10000) { body = body.substring(0, 10000); }   // 与 MAX_TEXT_LENGTH 对齐
    var desc = (api.description || '').replace(/[\r\n]+/g, ' ').replace(/^\s+|\s+$/g, '');
    if (desc.length > 120) { desc = desc.substring(0, 120); }
    return J({
        title: desc ? desc : (firstKey + ' · gist'),
        description: firstKey + ' · GitHub Gist',
        body: body,
        textOnly: true
    });
}

// GitHub 插件 · resolve 步骤：按源链接形态分派，主路径完全不碰 api.github.com。
// 为什么打 raw 不打 API：api.github.com 未认证配额 60 次/时且按出口 IP 计（共享出口
// IP 时随时可能被别人耗尽），2026-10-01 用户实测 yang0/handraw-style 导入报
// 「接口没有返回内容」即为配额耗尽后的 403 被笼统吞掉。raw.githubusercontent.com
// 是 CDN、无此配额：仓库主页直接取 HEAD/README.md；仅当没有 README.md（命名变体）
// 才落到 readme API 解析变体，那次才耗 1 点配额。
// 源链接形态让脚本看见的方式：模板把源链接原样缀在 vnsrc= 查询参数里（raw CDN 忽略
// 未知查询参数），脚本从 input.url 解回来。
// 状态码约定：老引擎遇非 2xx 根本不会运行本脚本，所以 status 缺失 ⇒ 2xx。
function extract(input) {
    var d = JSON.parse(input);
    var url = d.url || '';
    var status = d.status || 200;
    function J(o) { return JSON.stringify(o); }
    function err(m) { return J({ error: m }); }
    function segDec(s) { try { return decodeURIComponent(s); } catch (e) { return s; } }

    var srcM = /vnsrc=(.+)$/.exec(url);
    var src = srcM ? srcM[1] : '';
    var pm = /github\.com\/([^\/?#]+)\/([^\/?#]+)(?:\/([^\/?#]+)((?:\/[^\/?#]*)*))?/.exec(src);
    if (!pm) { return err('github: 无法从链接识别 owner/repo（' + src.slice(0, 80) + '）'); }
    var owner = pm[1], repo = pm[2], third = pm[3] || '';
    var rest = pm[4] || '';   // 形如 "/master/README.md"，保留前导 /

    if (third === 'blob' || third === 'raw') {
        var parts = rest.split('/');          // ['', ref, ...path]
        var ref = parts[1] || '';
        var path = parts.slice(2).join('/');
        if (!ref || !path) { return err('github: 文件链接缺 ref 或路径（' + src.slice(0, 80) + '）'); }
        var name = segDec(path.split('/').pop() || '');
        return J({
            nextURL: 'https://raw.githubusercontent.com/' + owner + '/' + repo + '/' + ref + '/' + path,
            title: (name || 'file') + ' · ' + owner + '/' + repo,
            description: 'GitHub 文件 · ' + owner + '/' + repo,
            githubKind: 'file'
        });
    }
    if (third === 'tree' || third === 'issues' || third === 'pull' || third === 'releases'
        || third === 'commit' || third === 'discussions' || third === 'wiki' || third === 'milestones') {
        return err('github: 暂不支持该 GitHub 页面（' + third + '）——文字解析现支持仓库主页与文件链接');
    }
    if (third !== '') { return err('github: 暂不支持该 GitHub 链接形态——现支持仓库主页与文件链接'); }

    // 仓库主页：本步已在取 HEAD/README.md
    if (status === 200) {
        // README.md 命中：正文就地成立。步骤链没有早退，nextURL 指向同一地址，
        // content 步幂等重取同文（raw CDN，无配额负担）
        var body = d.text || '';
        if (body.length > 10000) { body = body.substring(0, 10000); }
        return J({
            nextURL: url.split('?')[0],
            title: owner + '/' + repo,
            description: 'GitHub 仓库 README（README.md）',
            body: body,
            textOnly: true,
            githubKind: 'repo-readme'
        });
    }
    // README.md 缺失（本步 404 等）：交给 readme API 解析命名变体（README/rst/zh-CN 等）
    return J({
        nextURL: 'https://api.github.com/repos/' + owner + '/' + repo + '/readme',
        title: owner + '/' + repo,
        description: 'GitHub 仓库 README',
        githubKind: 'repo-api'
    });
}

// GitHub 插件 · content 步骤：取 resolve 步分派的 nextURL（三选一）落正文。
//   raw 文本（README.md 或 blob 文件）→ 正文即文本
//   readme API（仅当仓库没有 README.md 时走到）→ 响应 content 字段内联 base64，
//   纯 JS 解码取正文，免去「download_url 再发一跳」，把变体 README 也压进两步链。
// NUL 字节守卫：二进制文件经 decodeWebText 的 isoLatin1 兜底解码必然混入 \u0000
// （该兜底永不失败），借此把图片/压缩包挡在「文字卡片」之外。
// 状态码：新引擎 passNon2xx 时可见（403=限流/404=内容缺失），老引擎非 2xx 不进脚本。
function extract(input) {
    var d = JSON.parse(input);
    var url = d.url || '';
    var status = d.status || 200;
    var isAPI = url.indexOf('api.github.com/') !== -1;

    function J(o) { return JSON.stringify(o); }
    function err(m) { return J({ error: m }); }

    if (status < 200 || status >= 300) {
        if (isAPI) {
            var msg = '';
            try { msg = (JSON.parse(d.text || '{}') || {}).message || ''; } catch (e) { }
            if (status === 403 && /rate limit/i.test(msg)) {
                return J({ error: 'github: API 限流', rateLimited: true });
            }
            if (status === 404) { return err('github: 该仓库没有 README（或仓库不存在/为私有），无法导入为文字'); }
            return err('github: README 接口返回 HTTP ' + status);
        }
        if (status === 404) { return err('github: 内容不存在（文件已被删除或链接失效）'); }
        return err('github: 内容获取返回 HTTP ' + status);
    }

    var body;
    if (isAPI) {
        var api;
        try { api = JSON.parse(d.text || ''); } catch (e) { return err('github: README 接口响应不是 JSON'); }
        if (!api.content) { return err('github: 仓库没有可读的 README'); }
        body = b64ToUtf8(api.content);
        if (api.path) { return J({ body: body, textOnly: true, description: 'GitHub 仓库 README（' + api.path + '）' }); }
    } else {
        body = d.text || '';
    }
    if (!body) { return err('github: 内容为空'); }
    if (body.indexOf('\u0000') !== -1) { return err('github: 该文件是二进制内容，文字解析仅支持文本'); }
    if (body.length > 10000) { body = body.substring(0, 10000); }   // 与 MAX_TEXT_LENGTH 对齐
    return J({ body: body, textOnly: true });
}

// base64 → UTF-8 字符串（纯 JS，JSC 裸环境没有 atob）。4 字节 UTF-8（emoji 等）
// 按 surrogate pair 还原；GitHub API 的 content 每 60 字符夹换行，先剥掉非表内字符。
function b64ToUtf8(b64) {
    var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    var clean = String(b64 || '').replace(/[^A-Za-z0-9+\/=]/g, '');
    var bytes = [];
    for (var i = 0; i < clean.length; i += 4) {
        var e1 = chars.indexOf(clean.charAt(i));
        if (e1 < 0) { break; }
        var e2 = chars.indexOf(clean.charAt(i + 1));
        if (e2 < 0) { break; }
        var c2 = clean.charAt(i + 2), c3 = clean.charAt(i + 3);
        var e3 = c2 === '=' ? -1 : chars.indexOf(c2);
        var e4 = c3 === '=' ? -1 : chars.indexOf(c3);
        bytes.push((e1 << 2) | (e2 >> 4));
        if (e3 >= 0) { bytes.push(((e2 & 15) << 4) | (e3 >> 2)); }
        if (e4 >= 0) { bytes.push(((e3 & 3) << 6) | e4); }
    }
    var out = '';
    for (var j = 0; j < bytes.length; ) {
        var b = bytes[j];
        if (b < 0x80) { out += String.fromCharCode(b); j += 1; }
        else if (b < 0xE0) { out += String.fromCharCode(((b & 31) << 6) | (bytes[j + 1] & 63)); j += 2; }
        else if (b < 0xF0) { out += String.fromCharCode(((b & 15) << 12) | ((bytes[j + 1] & 63) << 6) | (bytes[j + 2] & 63)); j += 3; }
        else {
            var cp = ((b & 7) << 18) | ((bytes[j + 1] & 63) << 12) | ((bytes[j + 2] & 63) << 6) | (bytes[j + 3] & 63);
            cp -= 0x10000;
            out += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 1023));
            j += 4;
        }
    }
    return out;
}

// GitHub raw 直链插件：链接本身即正文（text/plain），标题取路径末段。
// NUL 字节守卫同 github 插件 content 步骤（二进制拒绝，不产垃圾文字卡片）。
// 状态码：新引擎 passNon2xx 时可见，404 给出可读错误；老引擎非 2xx 不进脚本。
function extract(input) {
    var d = JSON.parse(input);
    var text = d.text || '';
    var status = d.status || 200;
    if (status < 200 || status >= 300) {
        if (status === 404) { return JSON.stringify({ error: 'github-raw: 文件不存在或已被删除' }); }
        return JSON.stringify({ error: 'github-raw: 内容获取返回 HTTP ' + status });
    }
    if (!text) { return JSON.stringify({ error: 'github-raw: 内容为空' }); }
    if (text.indexOf('\u0000') !== -1) { return JSON.stringify({ error: 'github-raw: 二进制内容不支持文字解析' }); }
    var path = (d.url || '').replace(/^https?:\/\/[^\/]+\//, '');
    var name = path.split('/').pop() || '';
    try { name = decodeURIComponent(name); } catch (e) { }
    if (text.length > 10000) { text = text.substring(0, 10000); }   // 与 MAX_TEXT_LENGTH 对齐
    return JSON.stringify({
        title: name || 'raw 文件',
        description: 'GitHub raw 文件 · ' + path,
        body: text,
        textOnly: true
    });
}
